class Entity:
    def __init__(self, physics, graphics):
        self.physics, self.graphics = physics, graphics
        self.components = [physics, graphics]

    def update(self, dt):
        for c in self.components:
            c.update(self, dt)

    def __getattr__(self, name):        # expose the physics component's API
        return getattr(self.__dict__["physics"], name)
